var n=`0941-udon-soup`;var s=`world-0941`;var t=`JP`;var o=`east-asia`;var a=4;var m=37;var r={en:`Udon Soup`,ua:`Суп з удоном`};var u={en:`Udon Soup is a Japan dish made with light soy sauce, udon noodles, shiitake mushroom, tofu (firm). This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Суп з удоном, страва кухні країни Японія. Основні складники: світлий соєвий соус, локшина удон, шиїтаке, твердий тофу. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 17 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 17 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:17,i:[[`dashi-stock`,1400,`ml`],[`light-soy-sauce`,60,`ml`],[`mirin`,45,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 8 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 8 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:8,i:[[`udon-noodles`,440,`g`]]},{en:`Poach the listed ingredients in barely simmering liquid for about 9 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 9 хвилин до готовності й м’якості.`,t:[`poaching`],m:9,i:[[`shiitake-mushroom`,200,`g`],[`tofu-firm`,260,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`green-onion`,75,`g`],[`nori`,3,`pcs`]]}];var g={slug:n,id:s,country:`JP`,region:o,servings:4,minutes:37,title:r,text:u,steps:d};export{t as country,g as default,s as id,m as minutes,o as region,a as servings,n as slug,d as steps,u as text,r as title};